                    .build())
                .map(ResourceUtils::getId)
                .zipWith(Mono.just(userId1)))
            .flatMap(function((quotaId, userId1) -> cloudFoundryClient.organizations()
                .create(CreateOrganizationRequest.builder()
                    .name(organizationName)
