    /**
     * Constructor
     */
    private FieldConstraintsBuilder() {
        stringMapping = new HashMap<>();
        intMapping = new HashMap<>();
        startRange = 0;//no negatives!
        endRange = Integer.MAX_VALUE;
        specialChars = new HashSet<>();
        specialChars.add(SpecialChar.NONE);
