	public UUID uuid;
	public PlayerTextureStore skinBlob;
	public int clientVersion;

	public PacketHandshake latestHandshakePacket;
	public volatile int handShakeStatus = -1;
	private int length;

	private final Queue<Packet> packets = new LinkedList<>();
	private volatile boolean isConnected = true;

	public EncryptionSettings getEncryptionSettings() {
		return encryptionSettings;
	}

	public void regenerateEncryptionSettings() {
		encryptionSettings = new EncryptionSettings();
		// encryptionSettings.serverid = new BigInteger(130,
		// Main.random).toString(32).substring(0, 20);
		encryptionSettings.serverid = "";
		KeyPairGenerator keyPairGenerator;
		try {
			keyPairGenerator = KeyPairGenerator.getInstance("RSA");
		} catch (NoSuchAlgorithmException ex) {
			throw new RuntimeException("Server platfrom unsuported, cannot hash rsa", ex);
		}
		keyPairGenerator.initialize(1024);
		encryptionSettings.keyPair = keyPairGenerator.genKeyPair();
		encryptionSettings.verifyToken = new byte[16];
		Main.random.nextBytes(encryptionSettings.verifyToken);
	}

	public void forcePacketFlush() {
		synchronized (packets) {
			Packet p;
			while ((p = packets.poll()) != null) {
				ctx.write(p);
				// EnderLogger.debug("Out: "+p.toString());
				p.onSend(this);
			}
			ctx.flush();
		}
	}

	@Override
	public void channelRead(ChannelHandlerContext ctx, Object msg) {
		if (this.ctx == null)
			this.ctx = ctx;
		((Packet) msg).onRecieve(this);
		// EnderLogger.debug("in: " + msg);
		forcePacketFlush();
	}

	@Override
	public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
		EnderLogger.exception(cause);
		ctx.close();
		super.exceptionCaught(ctx, cause);
	}

	@Override
	public void channelInactive(ChannelHandlerContext ctx) throws Exception {
		this.onDisconnect();
		super.channelInactive(ctx);
	}

	private void onDisconnect() {
		if (this.isConnected == false) return;
		synchronized (packets) {
			if (this.isConnected == false) return;
			this.isConnected = false;
			this.packets.clear();
			if (player != null && player.isOnline()) {
				final EnderPlayer subPlayer = player;
				Main.getInstance().sendToMainThread(new Runnable() {

					@Override
					public void run() {
						subPlayer.onDisconnect();
					}
				});
				player.isOnline = false;
			}
		}
	}

	private MinecraftServerCodex codex;

	public MinecraftServerCodex createCodex() {
		return codex = new MinecraftServerCodex(this);
	}

	public MinecraftServerCodex getCodex() {
		return codex;
	}

	public void sendPacket(Packet... packets) {
		if (this.isConnected == false) return;
		synchronized (packets) {
			if (this.isConnected == false) return;
			for (Packet packet : packets) {
				this.packets.offer(packet);
			}
		}
	}

	public void setupEncryption(final SecretKey key) throws IOException {
		final Cipher decrypter = generateKey(2, key);
		final Cipher encrypter = generateKey(1, key);
		ctx.pipeline().addBefore("decrypt", "packet_rw_converter", new MessageToMessageDecoder<ByteBuf>() {

			NetworkEncrypter chipper = new NetworkEncrypter(decrypter);

			@Override
			protected void decode(ChannelHandlerContext ctx, ByteBuf in, List<Object> out) throws ShortBufferException {
				System.out.println("Decrypting " + in.readableBytes());
				this.chipper.decrypt(ctx, in);
			}

		});
		ctx.pipeline().addBefore("encrypt", "packet_rw_converter", new MessageToByteEncoder<ByteBuf>() {

			NetworkEncrypter chipper = new NetworkEncrypter(encrypter);

			@Override
			protected void encode(ChannelHandlerContext ctx, ByteBuf msg, ByteBuf out) throws Exception {
				System.out.println("Encrypting " + msg.readableBytes());
				this.chipper.encrypt(msg, out);
			}

		});
	}

	private static Cipher generateKey(int keyType, Key secretKey) throws IOException {
		try {
			Cipher localCipher = Cipher.getInstance("AES/CFB8/NoPadding");
			localCipher.init(keyType, secretKey, new IvParameterSpec(secretKey.getEncoded()));
			return localCipher;
		} catch (GeneralSecurityException localGeneralSecurityException) {
			throw new IOException("Unable to generate a encryption key", localGeneralSecurityException);
		}
	}

	public void spawnPlayer() {
		if (player != null)
			throw new IllegalStateException();
		if (this.uuid == null) {
			this.disconnect("Illegal uuid");
			return;
		}
		if (this.skinBlob == null)
			this.skinBlob = PlayerTextureStore.DEFAULT_STORE; // Null oject
																// design
																// pattern

		player = new EnderPlayer(wantedName, this, uuid, this.skinBlob);
		final Object lock = new Object();
		synchronized (lock) {
			Main.getInstance().sendToMainThread(new Runnable() {

				@Override
				public void run() {
					Main.getInstance().onlinePlayers.add(player);
					try {

						sendPacket(new PacketOutLoginSucces(player.uuid.toString(), player.getPlayerName()));

						sendPacket(new PacketOutJoinGame(player.getEntityId(), (byte) GameMode.SURVIVAL.getId(), (byte) 0, (byte) 1, (byte) 60, "default", false));

						EnderWorld mainWorld = Main.getInstance().mainWorld;
						Location spawn = mainWorld.getSpawn();
						Location loc = player.getLocation();
						loc.setX(spawn.getX());
						loc.setY(spawn.getY());
						loc.setZ(spawn.getZ());
						loc.setYaw(spawn.getYaw());
						loc.setPitch(spawn.getPitch());

						mainWorld.doChunkUpdatesForPlayer(player, player.chunkInformer, 1);
						player.onSpawn();
						sendPacket(new PacketOutSpawnPosition(spawn));

						int i = 0;
						if (player.isCreative)
							i = (byte) (i | 0x1);
						if (player.isFlying)
							i = (byte) (i | 0x2);
						if (player.canFly)
							i = (byte) (i | 0x4);
						if (player.godMode)
							i = (byte) (i | 0x8);

						sendPacket(new PacketOutPlayerAbilities((byte) i, 0.1F, 0.1F));
						sendPacket(new PacketOutPlayerPositionLook(loc.getX(), loc.getY(), loc.getZ(), loc.getYaw(), loc.getPitch(), (byte) 0b00000));
						sendPacket(new PacketOutUpdateHealth(player.getHealth(), player.food, player.foodSaturation));

					} catch (Exception e) {
						EnderLogger.exception(e);
					} finally {
						synchronized (lock) {
							lock.notifyAll();
						}
					}

				}
			});
			try {
				lock.wait();
			} catch (InterruptedException ex) {
				Thread.currentThread().interrupt();
			}
		}

	}

	public class EncryptionSettings {

		private String serverid;
		private KeyPair keyPair;
		private byte[] verifyToken;

		public String getServerid() {
			return serverid;
		}

		public KeyPair getKeyPair() {
			return keyPair;
		}

		public byte[] getVerifyToken() {
			return verifyToken;
		}
	}

	public void disconnect(String message) {
		this.disconnect(new SimpleMessage(message));
	}

	public void disconnect(Message message) {
		try {
			this.ctx.channel().pipeline().addFirst("packet_r_disconnected", new DiscardingReader());
			if (this.player == null)
				EnderLogger.info("Kicking unregistered channel (" + this.wantedName + "" + this.uuid + "): " + message.toPlainText());
			else
				EnderLogger.info("Kicking (" + this.wantedName + "," + this.uuid + "): " + message.toPlainText());
			Packet p = codex.getDisconnectionPacket(message);
			System.out.println(p);
			this.ctx.channel().pipeline().addFirst(new DiscardingReader());
			if (p != null)
				ctx.write(p);
		} catch (Exception ex) {
			EnderLogger.exception(ex);
		}
		finally
		{
			this.onDisconnect();
			ctx.close();
		}
	}
}

package org.enderstone.server.regions;

import java.lang.ref.Reference;
import java.lang.ref.WeakReference;
import java.util.LinkedList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.enderstone.server.EnderLogger;
import org.enderstone.server.Location;
import org.enderstone.server.Main;
import org.enderstone.server.entity.EnderPlayer;
import org.enderstone.server.packet.play.PacketOutBlockChange;

/**
 *
 * @author Fernando
 */
public class EnderChunk {

	protected final static int CHUNK_SECTION_SIZE = 16;
	protected final static int MAX_CHUNK_SECTIONS = 16;
	private static final Reference<EnderChunkMap> NULL_REFERENCE = new WeakReference(null);
	private final int z;
	private final short[][] blockID;
	private final byte[][] data;
	private final byte[] biome;
	private final List<BlockData> blockData;
	private final List<BlockData> activeBlockData = new LinkedList<>();
	private final int x;
	public boolean hasPopulated = false;
	private boolean isValid = true;

	public EnderChunk(int x, int z, short[][] blockID, byte[][] data, byte[] biome, List<BlockData> blockData) {
		this.z = z;
		this.blockID = blockID;
		this.data = data;
		this.biome = biome;
		this.blockData = blockData;
		this.x = x;
	}

	public int getZ() {
		return z;
	}

	public int getX() {
		return x;
	}

	@Override
	public int hashCode() {
		return this.x << 16 ^ this.z;
	}

	@Override
	public boolean equals(Object obj) {
		if (obj == null) {
			return false;
		}
		if (getClass() != obj.getClass()) {
			return false;
		}
		final EnderChunk other = (EnderChunk) obj;
		if (this.z != other.z) {
			return false;
		}
		return this.x == other.x;
	}

	/**
	 * MUST BE CALLED FROM MAIN THREAD
	 *
	 * @param x
	 * @param y
	 * @param z
	 * @param material
	 * @param data
	 */
	public void setBlock(int x, int y, int z, BlockId material, byte data) {
		// if the Block section the block is in hasn't been used yet, allocate
		// it
		if (!(y <= 256 && y >= 0 && x <= 16 && x >= 0 && z <= 16 && z >= 0)) {
			throw new ArrayIndexOutOfBoundsException("x must be: 0 <= x < 16 (" + x + ") &&" + " y must be: 0 <= y < 256 (" + y + ") &&" + " z must be: 0 <= z < 16 (" + z + ")");
		}
		if (data < 0 || data > 15) {
			throw new IllegalArgumentException("data must be: 0 <= data < 16 (" + data + ")");
		}
		if (material == null)
			material = BlockId.AIR;
		if (blockID[y >> 4] == null) {
			blockID[y >> 4] = new short[16 * 16 * 16];
			this.data[y >> 4] = new byte[16 * 16 * 16];
		}
		blockID[y >> 4][((y & 0xF) << 8) | (z << 4) | x] = material.getId();
		this.data[y >> 4][((y & 0xF) << 8) | (z << 4) | x] = data;

		for (EnderPlayer player : Main.getInstance().onlinePlayers) {
			if (Main.getInstance().mainWorld.players.containsKey(player)) {
				if (Main.getInstance().mainWorld.players.get(player).contains(this)) {
					try {
						player.getNetworkManager().sendPacket(new PacketOutBlockChange(new Location("", (this.getX() * 16) + x, y, (this.getZ() * 16) + z, (float) 0,(float) 0), material.getId(), data));
					} catch (Exception e) {
						EnderLogger.exception(e);
					}
				}
			}
		}
		compressed = NULL_REFERENCE;
	}

	public BlockId getBlock(int x, int y, int z) {
		if (!(y <= 256 && y >= 0 && x <= 16 && x >= 0 && z <= 16 && z >= 0)) {
			throw new ArrayIndexOutOfBoundsException("x must be: -1 < x < 16 (" + x + ") &&" + " y must be: -1 < y < 256 (" + y + ") &&" + " z must be: -1 < z < 16 (" + z + ")");
		}
		// if the Block section the block is in hasn't been used yet, allocate
		// it
		if (blockID[y >> 4] == null) {
			return BlockId.AIR; // block is air as it hasnt been allocated
		}
		return BlockId.byId(blockID[y >> 4][((y & 0xF) << 8) | (z << 4) | x]);

	}

	public byte getData(int x, int y, int z) {
		if (!(y <= 256 && y >= 0 && x <= 16 && x >= 0 && z <= 16 && z >= 0)) {
			throw new ArrayIndexOutOfBoundsException("x must be: -1 < x < 16 (" + x + ") &&" + " y must be: -1 < y < 256 (" + y + ") &&" + " z must be: -1 < z < 16 (" + z + ")");
		}
		// if the Block section the block is in hasn't been used yet, allocate
		// it
		if (data[y >> 4] == null) {
			return 0; // block is air as it hasnt been allocated
		}
		return data[y >> 4][((y & 0xF) << 8) | (z << 4) | x];

	}

	public Reference<EnderChunkMap> compressed = NULL_REFERENCE;

	/**
	 * Gets the format used by the chunk packet
	 *
	 * @return
	 */
	public EnderChunkMap getCompressedChunk() // TODO add block / skyligth
	{
		EnderChunkMap map;
		if ((map = compressed.get()) != null) {
			return map;
		}
		map = build(this, false, 65535);
		compressed = new WeakReference<>(map);
		return map;
	}

	public static EnderChunkMap build(EnderChunk chunk, boolean flag, int i) {
		int j = 0;

		int k = 0;
		EnderChunkMap chunkmap = new EnderChunkMap();
		byte[] abyte = new byte[196864];
		int l;
		/**
		 * Calculate bitmasks & empty sections
		 */
		{
			for (l = 0; l < chunk.blockID.length; ++l) {
				if (chunk.blockID[l] != null && (!flag) && (i & 1 << l) != 0) {
					chunkmap.primaryBitmap |= 1 << l;
					for (short s : chunk.blockID[l]) {
						if (s > 255) {
							// chunkmap.extendedBitmap |= 1 << l; // No support
							// for extended block ids
							++k;
							break;
						}
					}
				}
			}
		}
		/**
		 * Write first byte of block id's
		 */
		{
			for (l = 0; l < chunk.blockID.length; ++l) {
				if (chunk.blockID[l] != null && (!flag) && (i & 1 << l) != 0) {
					short[] abyte1 = chunk.blockID[l];
					for (int t = 0; t < abyte1.length; t++) {
						abyte[t + j] = (byte) abyte1[t];
					}
					j += abyte1.length;
				}
			}
		}
		/**
		 * Write data of blocks
		 */
		{
			for (l = 0; l < chunk.data.length; ++l) {
				if (chunk.data[l] != null && (!flag) && (i & 1 << l) != 0) {
					byte[] nibblearray = chunk.data[l];
					byte halfData = 0;
					boolean hd = false;

					for (byte block : nibblearray) {
						if (hd) {
							halfData = (byte) ((block << 4) | halfData);
							abyte[j++] = halfData;
						} else {
							halfData = block;
						}
						hd = !hd;
					}
					// j += nibblearray.length / 2 ;
				}
			}
		}
		/**
		 * Block Ligth - uses data because its the same size as the ligthing array we don't have
		 */
		{
			for (l = 0; l < chunk.data.length; ++l) {
				if (chunk.data[l] != null && (!flag) && (i & 1 << l) != 0) {
					byte[] nibblearray = chunk.data[l];
					byte halfData = 0;
					boolean hd = false;

					for (byte block : nibblearray) {
						byte blockLigth = 0;
						if (hd) {
							halfData = (byte) ((blockLigth << 4) | halfData);
							abyte[j++] = halfData;
						} else {
							halfData = blockLigth;
						}
						hd = !hd;
					}
					// j += nibblearray.length / 2 ;
				}
			}
		}
		/**
		 * Sky light - uses blockid because its the same size as the sky array we don't have
		 */
		{
			for (l = 0; l < chunk.blockID.length; ++l) {
				if (chunk.blockID[l] != null && (!flag) && (i & 1 << l) != 0) {
					short[] nibblearray = chunk.blockID[l];
					byte halfData = 0;
					boolean hd = false;

					for (short block : nibblearray) {
						byte skyLigth = (byte) (block == 0 ? 15 : 0);
						if (hd) {
							halfData = (byte) ((skyLigth << 4) | halfData);
							abyte[j++] = halfData;
						} else {
							halfData = skyLigth;
						}
						hd = !hd;
					}
					// j += nibblearray.length / 2 ;
				}
			}
		}
		/**
		 * Extended blocks, skip this
		 */
		{

		}
		/**
		 * Biomes
		 */
		{
			if (flag) {
				byte[] abyte2 = chunk.biome;

				System.arraycopy(abyte2, 0, abyte, j, abyte2.length);
				j += abyte2.length;
			}
		}
		/**
		 * Copy
		 */
		chunkmap.chunkData = new byte[j];
		System.arraycopy(abyte, 0, chunkmap.chunkData, 0, j);

		return chunkmap;
	}

	public int getHighestBlock(int x, int z) {
		for (int i = 255; i > 0; i--) {
